40	
41	import org.jboss.logging.Logger;
42	
43	import static org.keycloak.representations.AccessToken.REALM_ACCESS;
44	import static org.keycloak.representations.AccessToken.RESOURCE_ACCESS;
45	
46	/**
47	 * @author <a href="mailto:mposolda@redhat.com">Marek Posolda</a>
48	 */
49	public class TokenUtil {
50	
51	    public static final String TOKEN_TYPE_BEARER = "Bearer";
52	
53	    public static final String TOKEN_TYPE_DPOP = "DPoP";
54	
55	    // Mentioned in the token-exchange specification https://datatracker.ietf.org/doc/html/rfc8693#name-successful-response
56	    public static final String TOKEN_TYPE_NA = "N_A";
57	
58	    // JWT Access Token types from https://datatracker.ietf.org/doc/html/rfc9068#section-2.1
59	    public static final String TOKEN_TYPE_JWT_ACCESS_TOKEN = "at+jwt";
60	    public static final String TOKEN_TYPE_JWT_ACCESS_TOKEN_PREFIXED = "application/" + TOKEN_TYPE_JWT_ACCESS_TOKEN;
61	
62	    // https://openid.net/specs/openid-connect-backchannel-1_0.html#LogoutToken
63	    public static final String TOKEN_TYPE_JWT_LOGOUT_TOKEN = "logout+jwt";
64	
65	    public static final String TOKEN_TYPE_KEYCLOAK_ID = "Serialized-ID";
66	
67	    public static final String TOKEN_TYPE_ID = "ID";
68	
69	    public static final String TOKEN_TYPE_REFRESH = "Refresh";
70	
71	    public static final String TOKEN_TYPE_OFFLINE = "Offline";
72	
73	    public static final String TOKEN_TYPE_LOGOUT = "Logout";
74	
75	    public static final String TOKEN_BACKCHANNEL_LOGOUT_EVENT = "http://schemas.openid.net/event/backchannel-logout";
76	    
77	    public static final String TOKEN_BACKCHANNEL_LOGOUT_EVENT_REVOKE_OFFLINE_TOKENS = "revoke_offline_access";
78	
79	    private static final Logger logger = Logger.getLogger(TokenUtil.class);
80	
81	    public static String attachOIDCScope(String scopeParam) {
82	        if (scopeParam == null || scopeParam.isEmpty()) {
83	            return OAuth2Constants.SCOPE_OPENID;
84	        } else if (hasScope(scopeParam, OAuth2Constants.SCOPE_OPENID)) {
85	            return scopeParam;
86	        } else {
87	            return OAuth2Constants.SCOPE_OPENID + " " + scopeParam;
88	        }
89	    }
90	
91	    public static boolean isOIDCRequest(String scopeParam) {
92	        return hasScope(scopeParam, OAuth2Constants.SCOPE_OPENID);
93	    }
94	
95	    public static boolean isOfflineTokenRequested(String scopeParam) {
96	        return hasScope(scopeParam, OAuth2Constants.OFFLINE_ACCESS);
97	    }
98	
99	    public static boolean hasScope(String scopeParam, String targetScope) {
100	        if (scopeParam == null || targetScope == null) {
101	            return false;
102	        }
103	
104	        String[] scopes = scopeParam.split(" ");
105	        for (String scope : scopes) {
106	            if (targetScope.equals(scope)) {
107	                return true;
108	            }
109	        }
110	        return false;
111	    }
112	
113	
114	    public static boolean hasPrompt(String promptParam, String targetPrompt) {
115	        if (promptParam == null || targetPrompt == null) {
116	            return false;
117	        }
118	
119	        String[] prompts = promptParam.split(" ");
120	        for (String prompt : prompts) {
121	            if (targetPrompt.equals(prompt)) {
122	                return true;
123	            }
124	        }
125	        return false;
126	    }
127	
128	
129	
130	    /**
131	     * Return refresh token or offline token
132	     *
133	     * @param decodedToken
134	     * @return
135	     */
136	    public static RefreshToken getRefreshToken(byte[] decodedToken) throws JWSInputException {
137	        try {
138	            return KeycloakJsonMapperFactory.mapper().readValue(decodedToken, RefreshToken.class);
139	        } catch (IOException e) {
140	            throw new JWSInputException(e);
141	        }
142	    }
143	
144	    public static RefreshToken getRefreshToken(String refreshToken) throws JWSInputException {
145	        byte[] encodedContent = new JWSInput(refreshToken).getContent();
146	        return getRefreshToken(encodedContent);
147	    }
148	
149	    /**
150	     * Return true if given refreshToken represents offline token
151	     *
152	     * @param refreshToken
153	     * @return
154	     */
155	    public static boolean isOfflineToken(String refreshToken) throws JWSInputException {
156	        RefreshToken token = getRefreshToken(refreshToken);
157	        return token.getType().equals(TOKEN_TYPE_OFFLINE);
158	    }
159	
160	
161	    public static String jweDirectEncode(Key aesKey, Key hmacKey, JsonWebToken jwt) throws JWEException {
162	        try {
163	            byte[] contentBytes = KeycloakJsonMapperFactory.mapper().writeValueAsBytes(jwt);
164	            return jweDirectEncode(aesKey, hmacKey, contentBytes);
165	        } catch (IOException ioe) {
166	            throw new JWEException(ioe);
167	        }
168	    }
169	
170	
171	    public static <T extends JsonWebToken> T jweDirectVerifyAndDecode(Key aesKey, Key hmacKey, String jweStr, Class<T> expectedClass) throws JWEException {
172	        byte[] contentBytes = jweDirectVerifyAndDecode(aesKey, hmacKey, jweStr);
173	        try {
174	            return KeycloakJsonMapperFactory.mapper().readValue(contentBytes, expectedClass);
175	        } catch (IOException ioe) {
176	            throw new JWEException(ioe);
177	        }
178	    }
179	
180	    public static String jweKeyEncryptionEncode(Key encryptionKEK, byte[] contentBytes, String algAlgorithm, String encAlgorithm, String kid, JWEAlgorithmProvider jweAlgorithmProvider, JWEEncryptionProvider jweEncryptionProvider) throws JWEException {
181	        return jweKeyEncryptionEncode(encryptionKEK, contentBytes, algAlgorithm, encAlgorithm, kid, jweAlgorithmProvider, jweEncryptionProvider, "JWT");
182	    }
183	
184	    public static String jweKeyEncryptionEncode(Key encryptionKEK, byte[] contentBytes, String algAlgorithm,
185	                                                String encAlgorithm, String kid, JWEAlgorithmProvider jweAlgorithmProvider,
186	                                                JWEEncryptionProvider jweEncryptionProvider, String jweContentType) throws JWEException {
187	        JWEHeader jweHeader = new JWEHeader(algAlgorithm, encAlgorithm, null, kid, jweContentType);
188	        return jweKeyEncryptionEncode(encryptionKEK, contentBytes, jweHeader, jweAlgorithmProvider, jweEncryptionProvider);
189	    }
190	
191	    private static String jweKeyEncryptionEncode(Key encryptionKEK, byte[] contentBytes, JWEHeader jweHeader, JWEAlgorithmProvider jweAlgorithmProvider, JWEEncryptionProvider jweEncryptionProvider) throws JWEException {
192	        JWE jwe = new JWE()
193	                .header(jweHeader)
194	                .content(contentBytes);
195	        jwe.getKeyStorage()
196	                .setEncryptionKey(encryptionKEK);
197	        String encodedContent = jwe.encodeJwe(jweAlgorithmProvider, jweEncryptionProvider);
198	        return encodedContent;
199	    }
200	
201	    public static byte[] jweKeyEncryptionVerifyAndDecode(Key decryptionKEK, String encodedContent) throws JWEException {
202	        JWE jwe = new JWE();
203	        jwe.getKeyStorage()
204	            .setDecryptionKey(decryptionKEK);
205	        jwe.verifyAndDecodeJwe(encodedContent);
206	        return jwe.getContent();
207	    }
208	
209	    public static byte[] jweKeyEncryptionVerifyAndDecode(Key decryptionKEK, String encodedContent, JWEAlgorithmProvider algorithmProvider, JWEEncryptionProvider encryptionProvider) throws JWEException {
210	        JWE jwe = new JWE();
211	        jwe.getKeyStorage()
212	            .setDecryptionKey(decryptionKEK);
213	        jwe.verifyAndDecodeJwe(encodedContent, algorithmProvider, encryptionProvider);
214	        return jwe.getContent();
215	    }
216	
217	    public static String jweDirectEncode(Key aesKey, Key hmacKey, byte[] contentBytes) throws JWEException {
218	        return jweDirectEncode(null, aesKey, hmacKey, contentBytes);
219	    }
220	
221	    public static String jweDirectEncode(String kid, Key aesKey, Key hmacKey, byte[] contentBytes) throws JWEException {
222	        int keyLength = aesKey.getEncoded().length;
223	        String encAlgorithm;
224	        switch (keyLength) {
225	            case 16: encAlgorithm = hmacKey != null ? JWEConstants.A128CBC_HS256 : JWEConstants.A128GCM;
226	                break;
227	            case 24: encAlgorithm = hmacKey != null ? JWEConstants.A192CBC_HS384 : JWEConstants.A192GCM;
228	                break;
229	            case 32: encAlgorithm = hmacKey != null ? JWEConstants.A256CBC_HS512 : JWEConstants.A256GCM;
230	                break;
231	            default: throw new IllegalArgumentException("Bad size for Encryption key: " + aesKey + ". Valid sizes are 16, 24, 32.");
232	        }
233	
234	        JWEHeader jweHeader = new JWEHeader(JWEConstants.DIRECT, encAlgorithm, null, kid);
235	        JWE jwe = new JWE()
236	                .header(jweHeader)
237	                .content(contentBytes);
238	
239	        jwe.getKeyStorage()
240	                .setCEKKey(aesKey, JWEKeyStorage.KeyUse.ENCRYPTION)
241	                .setCEKKey(hmacKey, JWEKeyStorage.KeyUse.SIGNATURE);
242	
243	        return jwe.encodeJwe();
244	
245	    }
246	
247	    public static byte[] jweDirectVerifyAndDecode(Key aesKey, Key hmacKey, String jweStr) throws JWEException {
248	        JWE jwe = new JWE();
249	        jwe.getKeyStorage()
250	                .setCEKKey(aesKey, JWEKeyStorage.KeyUse.ENCRYPTION)
251	                .setCEKKey(hmacKey, JWEKeyStorage.KeyUse.SIGNATURE);
252	
253	        jwe.verifyAndDecodeJwe(jweStr);
254	
255	        return jwe.getContent();
256	
257	    }
258	
259	    /**
260	     * If token contains claims like "realm_access" or "resource_access" inside the "otherClaims" map, then those would be merged with the original fields "realm_access"
261	     * and "resource_access", which are present directly on the token
262	     *
263	     * @param token access token
264	     */
265	    public static void convertTokenRolesFromOtherClaims(AccessToken token) {
266	        if (token.getOtherClaims() == null) return;
267	
268	        if (token.getOtherClaims().containsKey(REALM_ACCESS)) {
269	            AccessToken.Access otherClaimsRealmAccess = convertToAccess(token.getOtherClaims().get(REALM_ACCESS), REALM_ACCESS);
270	            if (otherClaimsRealmAccess != null) {
271	                token.setRealmAccess(mergeAccess(token.getRealmAccess(), otherClaimsRealmAccess));
272	                token.getOtherClaims().remove(REALM_ACCESS);
273	            }
274	        }
275	
276	        if (token.getOtherClaims().containsKey(RESOURCE_ACCESS)) {
277	            if (token.getOtherClaims().get(RESOURCE_ACCESS) instanceof Map) {
278	                Map<String, AccessToken.Access> mergedResourceAccess = null;
279	                for (Map.Entry<String, Object> entry : ((Map<String, Object>) token.getOtherClaims().get(RESOURCE_ACCESS)).entrySet()) {
280	                    String clientId = entry.getKey();
281	                    AccessToken.Access otherClaimsClientAccess = convertToAccess(entry.getValue(), RESOURCE_ACCESS + "." + clientId);
282	                    if (otherClaimsClientAccess != null) {
283	                        if (mergedResourceAccess == null) {
284	                            // Re-create as hashMap as it might be unmodifiable map
285	                            mergedResourceAccess = new HashMap<>(token.getResourceAccess());
286	                        }
287	                        AccessToken.Access mergedAccess = mergeAccess(token.getResourceAccess(clientId), otherClaimsClientAccess);
288	                        mergedResourceAccess.put(clientId, mergedAccess);
289	                    }
290	                }
291	                // Only consume the raw claim when at least one entry could be converted. If nothing
292	                // was converted (e.g. a JSON string injected via a user attribute protocol mapper),
293	                // keep the original claim so the token retains its content instead of an empty {}.
294	                if (mergedResourceAccess != null) {
295	                    token.setResourceAccess(mergedResourceAccess);
296	                    token.getOtherClaims().remove(RESOURCE_ACCESS);
297	                }
298	            } else {
299	                logger.warnf("Claim resource_access in the incorrect format in the access token of user %s. Ignoring", token.getPreferredUsername());
300	            }
301	        }
302	    }
303	
304	    private static AccessToken.Access convertToAccess(Object accessClaim, String claimName) {
305	        KeycloakJsonMapper jsonMapper = KeycloakJsonMapperFactory.mapper();
306	        try {
307	            return jsonMapper.readValue(jsonMapper.writeValueAsString(accessClaim), AccessToken.Access.class);
308	        } catch (IOException ioe) {
309	            logger.warnf( "Failed to convert roles from claim %s. Ignoring", claimName);
310	            return null;
311	        }
312	    }
313	
314	    private static AccessToken.Access mergeAccess(AccessToken.Access access1, AccessToken.Access access2) {
315	        if (access1 == null) return access2;
316	        if (access2 == null) return access1;
317	        access1.getRoles().addAll(access2.getRoles());
318	        return access1;
319	    }
320	}
